insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D5-S1-001', 'source'::public.t3a_content_family, 'The rota neither of you set', 'D5', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D5-S1-001", "title": "The rota neither of you set", "stage": 1, "stage_code": "S1", "demonstration": true, "serving_eligible": false, "scenario_class": "observation_ready", "d5_situation_class": "SC-D5-1", "interaction_pattern_family_id": "IPF-D5-01", "administration_form_id": "AF-S1-SEQUENTIAL-REVEAL", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"source_sheet_text": "`designated_positions`: DP-01 alternating first and second weekends month to month; DP-02 a fixed split with the participant on third and fourth; DP-03 the split set weekend by weekend each month. `designated_enquiries`: DE-01 what the first-weekend preference rests on; DE-02 what the rota template permits; DE-03 what the team lead needs by Friday. `shared_items`: SI-01 the rota template and its four weekends; SI-02 the service requirement of one person each weekend; SI-03 the Friday deadline. `available_options`: AO-01 alternating months; AO-02 fixed third and fourth; AO-03 weekend-by-weekend; AO-04 the team lead asked to set it (all q_d5_04b_eligible true, q_d5_05b_eligible true). `available_routes`: Empty. Directly to the colleague, in writing to the team lead and at the team meeting are not selectable, because a written response cannot evidence a route used. `counterpart_role`: the colleague sharing the rota — RETAINED, NEVER RENDERED. `counterpart_position`: the first two weekends every month — RETAINED, NEVER RENDERED. `difference_established`: the proposed split against the standing commitment, exact text at R1. `authority_relation`: the team lead approves but does not set. `agreement_contents`: AC-01 the split; AC-02 whether it is fixed or alternating; AC-03 who sends it to the team lead. `recording_route`: the rota template. `persistence_point`: Friday. `exchange_test_point`: R7. **IT PUTS AN ASSERTION THE RECORD CONTRADICTS — the record shows three of four, not two — so A3 is reachable.** `unsupported_inferences`: that either split is fairer; that conceding first weekends is accommodating; anything about give and take. `irrelevant_conduct`: the colleague''s commitment or reasoning, NEVER RECORDED.", "d5_situation_class": "SC-D5-1"}, "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A written response cannot evidence a route used. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "Its parent is not served"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents and a recording route"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "On Q-D5-07 A1 or A2"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "Friday is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "Test point at R7, and A3 is the answer the record supports"}], "script": null, "reveals": [], "text_blocks": {"The situation as the participant meets it": "You and a colleague share responsibility for a weekend support rota covering four weekends a month. The rota for next month has to be set this week.\nYour colleague has proposed taking the first two weekends every month. You have a standing commitment on first weekends.\nWhat the record shows: the rota template allows any split of the four; last month you took three of the four; the service requires one of you on each weekend; the team lead approves the rota but does not set it; and the rota is due Friday."}, "narrative": {"The situation as the participant meets it": "> You and a colleague share responsibility for a weekend support rota covering four weekends a month. The rota for next month has to be set this week.\n>\n> Your colleague has proposed taking the first two weekends every month. You have a standing commitment on first weekends.\n>\n> What the record shows: the rota template allows any split of the four; last month you took three of the four; the service requires one of you on each weekend; the team lead approves the rota but does not set it; and the rota is due Friday.", "Reveal sequence": "R1 the situation. R2 QUESTION: what do you state as your own position on the split? R3 QUESTION: what, if anything, do you ask? R4 QUESTION: what do you put forward? R5 QUESTION: is there anything in your own position you would change? R6 QUESTION: if the split is not settled by Friday, what happens? R7 EXCHANGE TEST: the team lead writes, \"You said you''d taken two weekends last month. Did you?\" — QUESTION: what do you say?", "What this fixture proves": "Q-D5-06 and Q-D5-06b are NOT SERVED and write no row, while every other D5 element is served from a written response. A build that writes a null, a not_applicable or a forced answer for an unserved question, or that withholds an element D5 serves at Stage 1, has failed."}, "source_version_hash": "e99ebd1242ccd025c85a6e108d50e5ccb4c134a73feeb28f8d0aa9430c1bf621"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D5-S1-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
