insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D5-S2-001', 'source'::public.t3a_content_family, 'The room booked twice', 'D5', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D5-S2-001", "title": "The room booked twice", "stage": 2, "stage_code": "S2", "demonstration": true, "serving_eligible": false, "scenario_class": "observation_ready", "d5_situation_class": "SC-D5-3", "interaction_pattern_family_id": "IPF-D5-03", "administration_form_id": "AF-S2-SEVEN-BEAT", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"source_sheet_text": "`designated_positions`: DP-01 the external workshop holds the afternoon; DP-02 the internal session moves to the free morning room; DP-03 the facilities coordinator reassigns. `designated_enquiries`: DE-01 what the other session requires of the room; DE-02 whether the morning room suits either session; DE-03 what the facilities coordinator can do. `shared_items`: SI-01 both bookings in the room system; SI-02 the second room free that morning; SI-03 the facilities coordinator''s ability to reassign. `available_options`: AO-01 the internal session moves to the morning room; AO-02 the workshop moves to the morning room; AO-03 the afternoon is split; AO-04 the coordinator decides (all performable in session, both flags true). `available_routes`: AR-01 this session. A joint note to the facilities coordinator and a note to both managers are not selectable: each can only be stated in the session, so each is an intention, not a route used. `counterpart_role`: the other team''s lead — RETAINED, NEVER RENDERED. `counterpart_position`: the source establishes none — RETAINED, NEVER RENDERED. `difference_established`: two bookings on one room. `authority_relation`: the facilities coordinator holds reassignment; neither party has authority over the other. `agreement_contents`: AC-01 who holds the afternoon; AC-02 which room the other uses; AC-03 who tells facilities. `recording_route`: the room system. `persistence_point`: the afternoon arrives and both are booked. `exchange_test_point`: B6, putting an assertion the record does not hold. `unsupported_inferences`: that external attendees outrank internal; that conceding the room is weak; anything about negotiation. `irrelevant_conduct`: the other team''s session or conduct, NEVER RECORDED.", "d5_situation_class": "SC-D5-3"}, "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-06", "state": "DIRECT", "basis": "One route completes in the session: the session itself"}, {"question": "Q-D5-06b", "state": "CONDITIONAL", "basis": "On Q-D5-06 A1"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "On Q-D5-07 A1 or A2"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The afternoon is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "Test point at B6, and A3 is reachable"}], "script": null, "reveals": [], "text_blocks": {}, "narrative": {"Participant pre-brief": "A client workshop room is booked by your team and by another team for the same afternoon. What the record shows: both bookings are in the room system and neither was flagged; your workshop has eight external attendees confirmed in writing; the other team''s session is internal; a second room of the same size is free that morning but not that afternoon; and the facilities coordinator can reassign either booking.", "Mentor brief": "The mentor reads the scripted lines of the other team''s lead, verbatim. **THE MENTOR FORMS NO VIEW OF THE OTHER TEAM''S LEAD AND RECORDS NOTHING ABOUT THEM.** No escalation, no repetition, no expressive reaction.", "The four questions": "B3 — \"Where do you stand on the room?\" B4 — \"What are you putting forward, and what would you move on?\" B5 — \"What would be agreed, and what if we cannot?\" B6 — \"Just so I have it right — you said your attendees were internal. Are they?\"", "What this fixture proves": "Two things. CE-D5-06 is served here and not at Stage 1, so a build that hard-codes route service by Stage passes one fixture and fails the other. And a note promised in the session is a spoken intention: a build that lists it as a route used turns speech into an act, which the source sheet rule at Section 5.5 forbids."}, "source_version_hash": "cb1fab013c9ded39efed606ac89b4cf20eec0f0b5863dd23f0c776a04e918e37"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D5-S2-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D5-S2-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 1, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D5-S2-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 2, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D5-S2-001' on conflict do nothing;
insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D5-S3-001', 'source'::public.t3a_content_family, 'The two halves that did not meet', 'D5', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D5-S3-001", "title": "The two halves that did not meet", "stage": 3, "stage_code": "S3", "demonstration": true, "serving_eligible": false, "scenario_class": "work_sample", "d5_situation_class": "SC-D5-4", "interaction_pattern_family_id": "IPF-D5-04", "administration_form_id": "AF-S3-ASYNC-SUBMISSION", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"source_sheet_text": "`designated_positions`: DP-01 the written schedule stands and the half arrives on the date; DP-02 the schedule is amended so the combining date moves three days; DP-03 the combining starts on what has arrived and completes on receipt. `designated_enquiries`: DE-01 what the other half requires to arrive on the date; DE-02 what the written schedule sets out in terms; DE-03 what a three-day move would do to the issue date. `shared_items`: SI-01 the written schedule both teams hold; SI-02 the half-day combining cost; SI-03 the issue date, not yet missed. `available_options`: AO-01 the schedule amended; AO-02 partial combining on receipt; AO-03 a checkpoint two days before the combining date; AO-04 the issue date moved (evidenced in the submitted work, both flags true). `available_routes`: Empty. A joint note to the other team lead, a joint schedule amendment and a call before the next cycle are not selectable, because a route a submission names is proposed, not used. `counterpart_role`: the other team lead — RETAINED, NEVER RENDERED. `counterpart_position`: the source establishes none; no reason has been recorded — RETAINED, NEVER RENDERED. **NO QUESTION RECOVERS WHY THE HALF ARRIVED LATE.** `difference_established`: two months late against a written schedule. `authority_relation`: peers; the two leads may amend jointly. `agreement_contents`: AC-01 the combining date; AC-02 any checkpoint; AC-03 what the schedule records. `recording_route`: the written schedule. `persistence_point`: the next cycle. `exchange_test_point`: **not_applicable. CE-D5-09 IS NOT IN LAUNCH DESIGN AT STAGE 3.** `unsupported_inferences`: that the other team failed, WHICH IS A D2 MATTER; that combining late was accommodating; anything about patience. `irrelevant_conduct`: the other team''s reasons, WHICH THE SOURCE DOES NOT ESTABLISH.", "d5_situation_class": "SC-D5-4"}, "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options; the brief asks for each"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options; the brief asks for each"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options; the brief asks for each"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options; the brief asks for each"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options; the brief asks for each"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A route the submission names is proposed, not used. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "Its parent is not served"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents and an amendable recording route"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "On Q-D5-07 A1 or A2"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The next cycle is the persistence point"}, {"question": "Q-D5-09", "state": "NOT SERVED", "basis": "Stage 3 launch design. NO ANSWER ROW, NO MISSING-STATE CODE, NO REPORT STATEMENT"}], "script": null, "reveals": [], "text_blocks": {"The brief as the participant meets it": "You and another team each produce half of a monthly analysis that is combined before issue. For the past two months the other half has arrived after the combining date and you have combined late.\nWhat the record shows: the combining date is in a written schedule both teams hold; the other half arrived three days late in each of the two months; combining takes half a day; the issue date has not yet been missed; the schedule can be amended by the two team leads together; and no reason for the lateness has been recorded.\nProduce: the position you would put; what you would ask; what you would propose and what you would move on; and what would be agreed, recorded and taken forward if it recurs."}, "narrative": {"The brief as the participant meets it": "> You and another team each produce half of a monthly analysis that is combined before issue. For the past two months the other half has arrived after the combining date and you have combined late.\n>\n> What the record shows: the combining date is in a written schedule both teams hold; the other half arrived three days late in each of the two months; combining takes half a day; the issue date has not yet been missed; the schedule can be amended by the two team leads together; and no reason for the lateness has been recorded.\n>\n> Produce: the position you would put; what you would ask; what you would propose and what you would move on; and what would be agreed, recorded and taken forward if it recurs.", "Submission": "Asynchronous. `min_seconds`, `max_seconds` and `mentor_action_sequence` NULL — null is not an error. Eleven provenance fields, three declarations, AI_USE_DECLARATION_REQUIRED in force; a missing tooling declaration refuses and logs.", "What this fixture proves": "Two questions, Q-D5-06 and Q-D5-09, produce no row of any kind, while every other element is served from the submission. A build that writes a null, a `not_applicable` or a \"not observed\" sentence for an unserved question has failed."}, "source_version_hash": "a46df7f6632dde139c95697e811e3894ec2e3c4961ff716be90e5c297e39d198"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D5-S3-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D5-S3-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 1, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D5-S3-001' on conflict do nothing;
