insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D5-S4-001', 'source'::public.t3a_content_family, 'Two handover practices, one client', 'D5', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D5-S4-001", "title": "Two handover practices, one client", "stage": 4, "stage_code": "S4", "demonstration": true, "serving_eligible": false, "scenario_class": "team_simulation", "d5_situation_class": "SC-D5-1", "interaction_pattern_family_id": "IPF-D5-01", "administration_form_id": "AF-S4-GROUP-ROUND", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"source_sheet_text": "`designated_positions`: DP-01 the written-note practice throughout; DP-02 the weekly-meeting practice throughout; DP-03 written notes with a monthly meeting. `designated_enquiries`: DE-01 what each practice requires at a handover; DE-02 what each was introduced to address; DE-03 what the client needs from a single point of contact. `shared_items`: SI-01 both practices documented and on file; SI-02 the eleven days to the client''s date; SI-03 the single client both groups serve. `available_options`: AO-01 written notes throughout; AO-02 weekly meeting throughout; AO-03 notes plus a monthly meeting; AO-04 the account office decides (all performable in session, both flags true). `available_routes`: AR-01 this session. A written practice note circulated to both groups and a route to the account office are not selectable: each can only be stated in the session, so each is an intention, not a route used. `counterpart_role`: the two group representatives and the account office — RETAINED, NEVER RENDERED. `counterpart_position`: two documented practices — RETAINED, NEVER RENDERED. `difference_established`: **two documented practices and the client''s end-of-month request, BOTH ESTABLISHED IN THE PRE-BRIEF AND NOT BY ANY CO-PARTICIPANT.** `authority_relation`: no lead named across the two groups. `agreement_contents`: AC-01 the practice; AC-02 the point of contact; AC-03 what the client is told. `recording_route`: the circulated practice note. `persistence_point`: the client''s end-of-month date. `exchange_test_point`: B6, putting an assertion the record contradicts — both practices are documented — so A3 is the answer the record supports. `unsupported_inferences`: that either practice is better; ANY COMPARISON OF WHAT P-OBS SAID AT B3 WITH B6 TO INFER WHETHER A POSITION HELD. `irrelevant_conduct`: the co-participants'' statements.", "d5_situation_class": "SC-D5-1"}, "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Each on its parent A1"}, {"question": "Q-D5-06", "state": "DIRECT", "basis": "One route completes in the session: the session itself"}, {"question": "Q-D5-06b", "state": "CONDITIONAL", "basis": "On Q-D5-06 A1"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents and a recording route"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "On Q-D5-07 A1 or A2"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The client date is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "Test point at B6, and A3 is the answer the record supports"}], "script": null, "reveals": [], "text_blocks": {}, "narrative": {"Model": "ONE OBSERVED PARTICIPANT (P-OBS), THREE CO-PARTICIPANTS (CP-1, CP-2, CP-3) who are role players and are NOT observed, one facilitator. ONE OBSERVATION RECORD, for P-OBS only. A Stage 4 group participation record is required for all four before entry. No recording.", "P-OBS pre-brief": "Two groups serving one client follow different documented handover practices and a single practice must be settled. What the record shows: one practice requires a written handover note per item; the other requires a weekly handover meeting; both are documented and on file; the client has asked for one point of contact by the end of the month; there are eleven days left; and no lead has been named across the two groups.", "CP positions": "CP-1: state the written-note practice and that it is documented. CP-2: state the weekly-meeting practice and that it is documented. CP-3, the account office: state the client''s end-of-month request and the eleven days.", "Facilitator card": "As Section 5.18, including: YOU MAKE NO NOTE OF HOW ANYTHING WAS SAID, AND YOU FORM NO VIEW OF ANY CO-PARTICIPANT.", "The four questions": "B3 — \"Where do you stand on the handover practice?\" B4 — \"What are you putting forward, and what would you move on?\" B5 — \"What would be agreed, and what if it is not settled in eleven days?\" B6 — \"Just so the position is right — you said only the written-note practice was documented. Is that so?\"", "What this fixture proves": "All three co-participants restate facts the pre-brief already establishes — the two documented practices and the client''s date. **THE PRE-BRIEF AND SOURCE SHEET ESTABLISH THEM; THE CO-PARTICIPANTS DO NOT.** A build that lets a co-participant position populate `designated_positions`, `shared_items` or `available_options` will pass the other three fixtures and fail here."}, "source_version_hash": "315cb7f355a4d22e27939a5a7153d10bcab10dbf4d5759bf934ab4ecadb41ab9"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D5-S4-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D5-S4-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 1, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D5-S4-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 2, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D5-S4-001' on conflict do nothing;
